require __DIR__.'/includes/bootstrap.php';require_permission('dashboard.view');$pdo=db();
$campaign=$pdo->query("SELECT * FROM campaigns WHERE status='active' ORDER BY start_date DESC,id DESC LIMIT 1")->fetch();if(!$campaign)$campaign=['id'=>0,'name'=>'No active campaign','start_date'=>date('Y-m-d'),'deadline'=>date('Y-m-d'),'target_count'=>1,'timezone'=>config('app.timezone')];
$growth=growth_count_summary();$q=$pdo->prepare('SELECT COALESCE(SUM(drivers_registered),0) FROM daily_growth_counts WHERE activity_date BETWEEN ? AND ?');$q->execute([$campaign['start_date'],$campaign['deadline']]);$counted=(int)$q->fetchColumn();$today=$growth['today_drivers'];
$progress=campaign_progress($campaign,$counted,$today);$totalDrivers=$growth['total_drivers'];$weekDrivers=$growth['week_drivers'];$pending=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status NOT IN ('completed','cancelled')")->fetchColumn();$overdue=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status NOT IN ('completed','cancelled') AND due_at IS NOT NULL AND due_at<UTC_TIMESTAMP()")->fetchColumn();$completed=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status='completed'")->fetchColumn();$activeEmployees=(int)$pdo->query("SELECT COUNT(*) FROM employees WHERE employment_status='active'")->fetchColumn();
$daily=$pdo->query("SELECT activity_date d,drivers_registered c FROM daily_growth_counts WHERE activity_date>=CURDATE()-INTERVAL 14 DAY ORDER BY activity_date")->fetchAll();$taskStatus=$pdo->query("SELECT status,COUNT(*) c FROM tasks GROUP BY status ORDER BY c DESC")->fetchAll();$taskPriority=$pdo->query("SELECT priority,COUNT(*) c FROM tasks WHERE status NOT IN ('completed','cancelled') GROUP BY priority")->fetchAll();$workload=$pdo->query("SELECT e.full_name,COUNT(t.id) c FROM employees e LEFT JOIN tasks t ON t.primary_assignee_id=e.id AND t.status NOT IN ('completed','cancelled') WHERE e.employment_status='active' GROUP BY e.id,e.full_name ORDER BY c DESC LIMIT 8")->fetchAll();$recent=$pdo->query("SELECT a.*,u.email FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 8")->fetchAll();
$dailyLabels=array_map(fn($r)=>date('d M',strtotime($r['d'])),$daily);$dailyValues=array_map(fn($r)=>(int)$r['c'],$daily);$statusLabels=array_map(fn($r)=>ucwords(str_replace('_',' ',$r['status'])),$taskStatus);$statusValues=array_map(fn($r)=>(int)$r['c'],$taskStatus);$priorityLabels=array_map(fn($r)=>ucfirst($r['priority']),$taskPriority);$priorityValues=array_map(fn($r)=>(int)$r['c'],$taskPriority);$workLabels=array_map(fn($r)=>$r['full_name'],$workload);$workValues=array_map(fn($r)=>(int)$r['c'],$workload);
$title='Overview';$active='dashboard';include __DIR__.'/includes/header.php';?>
