er"><i data-lucide="list-todo"></i></span><span class="metric-tag">Work</span></div><p>Pending tasks</p><strong id="metricPending"><?=number_format($pending)?></strong><span class="metric-sub"><b class="danger-text" id="metricOverdue"><?=number_format($overdue)?></b> overdue</span></div><div class="metric-card"><div class="metric-head"><span class="metric-icon success"><i data-lucide="circle-check-big"></i></span><span class="metric-tag">Done</span></div><p>Completed tasks</p><strong id="metricCompleted"><?=number_format($completed)?></strong><span class="metric-sub">Across active operations</span></div><div class="metric-card"><div class="metric-head"><span class="metric-icon cyan"><i data-lucide="briefcase-business"></i></span><span class="metric-tag">Team</span></div><p>Active employees</p><strong id="metricEmployees"><?=number_format($activeEmployees)?></strong><a href="<?=e(url('employees.php'))?>">Manage team <i data-lucide="arrow-up-right"></i></a></div></section>
<section class="dashboard-grid reveal stagger-2"><article class="panel campaign-panel"><div class="panel-heading"><div><p class="eyebrow">Primary target</p><h3>Driver growth trajectory</h3></div><span class="status-chip <?=e($progress['pace_status'])?>" id="paceChip"><i data-lucide="activity"></i><?=e($progress['pace_status']==='on-track'?'On required pace':'Below required pace')?></span></div><div class="campaign-body"><div class="progress-orbit" style="--progress:<?=e((string)$progress['visual_percentage'])?>"><svg viewBox="0 0 190 190" role="img" aria-label="<?=e(number_format($progress['percentage'],1))?> percent of driver target achieved"><circle class="orbit-track" cx="95" cy="95" r="78"></circle><circle class="orbit-value" id="orbitValue" cx="95" cy="95" r="78" pathLength="100" stroke-dasharray="100" stroke-dashoffset="<?=e((string)(100-$progress['visual_percentage']))?>"></circle></svg><div class="orbit-center"><span id="orbitCount"><?=number_format($progress['counted'])?> / <?=number_format($progress['target'])?></span><strong id="orbitPercent"><?=number_format($progress['percentage'],1)?>%</strong><small>complete</small></div></div><div class="pace-grid"><div><span>Avg. registrations / day</span><strong id="avgDaily"><?=number_format($progress['average_daily'],1)?></strong><small>actual pace</small></div><div><span>Required / remaining day</span><strong id="requiredDaily"><?=number_format($progress['required_daily'],1)?></strong><small>to meet deadline</small></div><div><span>Planned to date</span><strong id="plannedToDate"><?=number_format($progress['planned_to_date'],0)?></strong><small>cumulative target</small></div><div><span>Projected completion</span><strong id="projectedDate"><?=e($progress['projected_completion_date']?date('d M',strtotime($progress['projected_completion_date'])):'—')?></strong><small>based on current pace</small></div></div></div><div class="linear-progress"><span id="linearProgress" style="width:<?=e((string)$progress['visual_percentage'])?>%"></span></div><div class="campaign-footer"><span><?=e(date('d M',strtotime($progress['start_date'])))?> start</span><strong id="remainingDrivers"><?=number_format($progress['remaining'])?> drivers remaining</strong><span><?=e(date('d M',strtotime($progress['deadline'])))?> deadline</span></div></article><article class="panel"><div class="panel-heading"><div><p class="eyebrow">14-day pulse</p><h3>Verified registrations</h3></div><a class="text-link" href="<?=e(url('reports.php'))?>">View report</a></div><div class="chart-wrap tall"><canvas id="registrationChart"></canvas></div></article></section>
<section class="analytics-grid reveal stagger-3"><article class="panel"><div class="panel-heading"><div><p class="eyebrow">Execution</p><h3>Tasks by status</h3></div></div><div class="chart-wrap"><canvas id="statusChart"></canvas></div></article><article class="panel"><div class="panel-heading"><div><p class="eyebrow">Work mix</p><h3>Open tasks by priority</h3></div></div><div class="chart-wrap"><canvas id="priorityChart"></canvas></div></article><article class="panel"><div class="panel-heading"><div><p class="eyebrow">Capacity</p><h3>Employee workload</h3></div></div><div class="chart-wrap"><canvas id="workloadChart"></canvas></div></article></section>
